import React, { useState } from "react";
import './wordle.css';
import Grid from './components/grid';
import Keyboard from "./components/keyboard";
import KeyboardListener from "../../keyboardlistener";

const DefaultWordle: React.FC = () => {
    const [keysPressed, setKeysPressed] = useState<string>('');
    const [number, setNumber] = useState(0);
    const [guesses, setGuesses] = useState<string[]>(Array(6).fill('')); 

    const handleKeyPress = (key: string) => {
        setKeysPressed((prev) => {
            if (key === 'Backspace')
                return prev.slice(0,-1);
            else if (key === 'Enter' && prev.length === 5) {
                setNumber((prevGuess) => {
                    setGuesses(guesses => {
                        if (prevGuess < guesses.length)
                            guesses[prevGuess] = prev;
                        return guesses;
                    })
                        if(prevGuess < 6)
                            return prevGuess + 1;
                        return prevGuess
                    }
                );
                return '';
            }
            else {
                if (prev.length < 5 && key.length === 1){
                    console.log(prev);
                    return prev+key.toUpperCase();
                }
                else {
                    console.log("Max word length reached");
                    return prev;
                }
            }
        });
    };
    return(
        <>
            <div className="defaultwordlecontainer">
                <KeyboardListener onKeyPress={handleKeyPress} />
                <Grid word = {keysPressed} guessNumber={number} guesses = {guesses}/>
            </div>
        </>
    );
}

export default DefaultWordle;
